#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<ll> x(n), y(n), r(n);
    for (int i = 0; i < n; i++) scanf("%lld %lld %lld", &x[i], &y[i], &r[i]);
    // reach[i] = bombs reachable from i (directed, includes i itself).
    vector<bitset<1000>> reach(n);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if ((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]) <= r[i] * r[i]) reach[i][j] = 1;
    // Warshall closure on bitsets: every row that reaches k absorbs k's row.
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++)
            if (reach[i][k]) reach[i] |= reach[k];
    size_t best = 0;
    for (auto &row : reach) best = max(best, row.count());
    printf("%zu\n", best);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] x = new long[n], y = new long[n], r = new long[n];
        for (int i = 0; i < n; i++) {
            st.nextToken(); x[i] = (long) st.nval;
            st.nextToken(); y[i] = (long) st.nval;
            st.nextToken(); r[i] = (long) st.nval;
        }
        int w = (n + 63) / 64;
        // reach[i] = bitset of bombs reachable from i (directed, includes i itself).
        long[][] reach = new long[n][w];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                long dx = x[i] - x[j], dy = y[i] - y[j];
                if (dx * dx + dy * dy <= r[i] * r[i]) reach[i][j >> 6] |= 1L << (j & 63);
            }
        // Warshall closure on bitsets: every row that reaches k absorbs k's row.
        for (int k = 0; k < n; k++) {
            long[] row = reach[k];
            for (int i = 0; i < n; i++)
                if ((reach[i][k >> 6] >>> (k & 63) & 1) == 1)
                    for (int t = 0; t < w; t++) reach[i][t] |= row[t];
        }
        int best = 0;
        for (long[] row : reach) {
            int c = 0;
            for (long v : row) c += Long.bitCount(v);
            best = Math.max(best, c);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	x, y, r := make([]int64, n), make([]int64, n), make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &x[i], &y[i], &r[i])
	}
	w := (n + 63) / 64
	// reach[i] = bitset of bombs reachable from i (directed, includes i itself).
	reach := make([][]uint64, n)
	for i := range reach {
		reach[i] = make([]uint64, w)
		for j := 0; j < n; j++ {
			dx, dy := x[i]-x[j], y[i]-y[j]
			if dx*dx+dy*dy <= r[i]*r[i] {
				reach[i][j>>6] |= 1 << (j & 63)
			}
		}
	}
	// Warshall closure on bitsets: every row that reaches k absorbs k's row.
	for k := 0; k < n; k++ {
		row := reach[k]
		for i := 0; i < n; i++ {
			if reach[i][k>>6]>>(k&63)&1 == 1 {
				for t := range row {
					reach[i][t] |= row[t]
				}
			}
		}
	}
	best := 0
	for _, row := range reach {
		c := 0
		for _, v := range row {
			c += bits.OnesCount64(v)
		}
		best = max(best, c)
	}
	fmt.Println(best)
}
